using Json=nlohmann::json;
glm::vec3 vector(const Json &j){auto a=j.get<std::array<float,3>>();for(float x:a)if(!std::isfinite(x))throw std::invalid_argument("PT package: non-finite vector");return {a[0],a[1],a[2]};}
