std::filesystem::path local(const std::filesystem::path &root,const Json &value){auto p=std::filesystem::path(value.get<std::string>());if(p.empty()||p.is_absolute())throw std::invalid_argument("PT package: expected a relative asset path");for(const auto &part:p)if(part=="..")throw std::invalid_argument("PT package: parent asset traversal");auto resolved=std::filesystem::weakly_canonical(root/p);auto relative=resolved.lexically_relative(std::filesystem::weakly_canonical(root));if(relative.empty()||*relative.begin()=="..")throw std::invalid_argument("PT package: asset escapes package");return resolved;}
std::vector<float> floats(const std::filesystem::path &path,uint64_t offset,uint64_t count){if(count>uint64_t(1)<<28)throw std::length_error("PT package: oversized float buffer");auto bytes=std::filesystem::file_size(path);if(offset>bytes||count>(bytes-offset)/4)throw std::invalid_argument("PT package: truncated float buffer");std::ifstream f(path,std::ios::binary);f.seekg(offset);std::vector<float> a(count);f.read(reinterpret_cast<char*>(a.data()),std::streamsize(count*4));if(!f)throw std::runtime_error("PT package: cannot read float buffer");for(float x:a)if(!std::isfinite(x))throw std::invalid_argument("PT package: non-finite float buffer");return a;}
