    if(std::filesystem::file_size(path)>32*1024*1024)throw std::length_error("PT package: oversized manifest");std::ifstream input(path);Json j;input>>j;const auto manifestSeconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-started).count();
    if(j.at("format")!="SceneRenderer.PT.v1")throw std::invalid_argument("PT package: unsupported format");
    auto root=std::filesystem::path(path).parent_path();auto binary=local(root,j.at("geometry"));std::ifstream meshFile(binary,std::ios::binary);char magic[8];meshFile.read(magic,8);if(!meshFile||std::memcmp(magic,"PTMESH01",8))throw std::invalid_argument("PT package: invalid mesh header");
