    auto camera=matrix(j.at("camera").at("world")),projection=matrix(j.at("camera").at("projection"));float sourceAspect=j.at("camera").at("aspect").get<float>();if(!std::isfinite(sourceAspect)||sourceAspect<=0)throw std::invalid_argument("PT package: invalid camera aspect");projection[0][0]*=sourceAspect/(float(width)/height);
