        if(glm::any(glm::lessThan(draw.pathTracingAbsorption,glm::vec3(0)))||glm::any(glm::lessThan(draw.pathTracingScattering,glm::vec3(0)))||!std::isfinite(draw.pathTracingAnisotropy)||std::abs(draw.pathTracingAnisotropy)>=.99f)throw std::invalid_argument("PT package: invalid medium coefficients");
